package com.campus.registration.service; import com.campus.registration.model.*;import java.util.*; public class PrerequisiteGraph{private final Map<String,Set<String>>g=new HashMap<>();public void add(Course c){g.computeIfAbsent(c.code(),k->new HashSet<>()).addAll(c.prerequisites());for(String p:c.prerequisites())g.computeIfAbsent(p,k->new HashSet<>());}public boolean satisfied(String c,Set<String>done){return g.getOrDefault(c,Set.of()).stream().allMatch(done::contains);}public List<String>topologicalOrder(){Map<String,Integer>d=new HashMap<>();Map<String,List<String>>rev=new HashMap<>();for(var e:g.entrySet()){d.putIfAbsent(e.getKey(),0);for(String p:e.getValue()){d.merge(e.getKey(),1,Integer::sum);rev.computeIfAbsent(p,k->new ArrayList<>()).add(e.getKey());}}Queue<String>q=new PriorityQueue<>();d.forEach((k,v)->{if(v==0)q.add(k);});List<String>o=new ArrayList<>();while(!q.isEmpty()){String x=q.poll();o.add(x);for(String n:rev.getOrDefault(x,List.of()))if(d.merge(n,-1,Integer::sum)==0)q.add(n);}if(o.size()!=d.size())throw new IllegalStateException("Prerequisite cycle detected");return o;}}